 const rows=result.data.map(item=>`<tr><td>${new Date(item.recordedAt).toLocaleString()}</td><td>${item.ticketDeleted?`${esc(item.ticketKey)} · ${esc(item.taskName)} (deleted)`:`<button class="task-title" data-bug-edit="${esc(item.issueId)}">${esc(item.ticketKey)} · ${esc(item.taskName)}</button>`}</td><td>${esc(item.projectName)}</td><td>${esc(labels[item.event]||item.event)}</td><td>${esc(item.event==='status_changed'?item.previousStatus+' → '+item.status:item.status)}</td></tr>`).join('');
 if(pageNumber===1)box.innerHTML=`<div class="panel bug-table-wrap"><table class="bug-table"><thead><tr><th>Recorded</th><th>Ticket</th><th>Project</th><th>Event</th><th>Status</th></tr></thead><tbody>${rows||'<tr><td colspan="5">No task history recorded for this member.</td></tr>'}</tbody></table></div>`;else box.querySelector('tbody').insertAdjacentHTML('beforeend',rows);
